import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for CoreFunction.functionID
 */
public class CoreFunction_functionID_TriageGen2Test {

    private CoreFunction coreFunction;
    private EvalContext mockContext;
    private JXPathContext mockJXPathContext;
    private NodePointer mockNodePointer;
    private Expression mockArg1;
    private Method functionIDMethod;

    @Before
    public void setUp() throws Exception {
        // CoreFunction constructor requires functionCode and Expression array
        mockArg1 = mock(Expression.class);
        Expression[] args = new Expression[]{mockArg1};
        // Assuming a dummy function code, e.g., 1
        coreFunction = new CoreFunction(1, args);

        mockContext = mock(EvalContext.class);
        mockJXPathContext = mock(JXPathContext.class);
        mockNodePointer = mock(NodePointer.class);

        when(mockContext.getJXPathContext()).thenReturn(mockJXPathContext);
        when(mockJXPathContext.getContextPointer()).thenReturn(mockNodePointer);

        // Accessing protected method via reflection
        functionIDMethod = CoreFunction.class.getDeclaredMethod("functionID", EvalContext.class);
        functionIDMethod.setAccessible(true);
    }

    @Test
    public void testFunctionID_Success() throws Exception {
        String targetId = "testId123";
        Object expectedResult = new Object();

        // Mocking the behavior of the arguments and the pointer
        when(mockArg1.computeValue(mockContext)).thenReturn(targetId);
        when(mockNodePointer.getPointerByID(mockJXPathContext, targetId)).thenReturn(expectedResult);

        // We need to mock InfoSetUtil.stringValue which is a static method
        try (MockedStatic<InfoSetUtil> infoSetUtilMockedStatic = Mockito.mockStatic(InfoSetUtil.class)) {
            infoSetUtilMockedStatic.when(() -> InfoSetUtil.stringValue(targetId)).thenReturn(targetId);

            Object result = functionIDMethod.invoke(coreFunction, mockContext);

            assertEquals(expectedResult, result);
        }
    }

    @Test(expected = Exception.class)
    public void testFunctionID_ArgumentCountMismatch() throws Exception {
        // Create a CoreFunction with 0 arguments to trigger assertArgCount(1) failure
        CoreFunction emptyFunction = new CoreFunction(1, new Expression[0]);

        // This should throw an IllegalArgumentException (or similar) from assertArgCount
        functionIDMethod.invoke(emptyFunction, mockContext);
    }

    @Test
    public void testFunctionID_NullIdHandling() throws Exception {
        // If the computed value is null, InfoSetUtil.stringValue usually returns an empty string or null
        when(mockArg1.computeValue(mockContext)).thenReturn(null);

        try (MockedStatic<InfoSetUtil> infoSetUtilMockedStatic = Mockito.mockStatic(InfoSetUtil.class)) {
            // Simulate InfoSetUtil returning null for null input
            infoSetUtilMockedStatic.when(() -> InfoSetUtil.stringValue(null)).thenReturn(null);

            // Mock pointer to return null when searching for null ID
            when(mockNodePointer.getPointerByID(mockJXPathContext, null)).thenReturn(null);

            Object result = functionIDMethod.invoke(coreFunction, mockContext);

            assertEquals(null, result);
        }
    }

    @Test
    public void testFunctionID_PointerReturnsNull() throws Exception {
        String targetId = "nonExistent";
        when(mockArg1.computeValue(mockContext)).thenReturn(targetId);

        try (MockedStatic<InfoSetUtil> infoSetUtilMockedStatic = Mockito.mockStatic(InfoSetUtil.class)) {
            infoSetUtilMockedStatic.when(() -> InfoSetUtil.stringValue(targetId)).thenReturn(targetId);

            // Simulate ID not being found in the pointer
            when(mockNodePointer.getPointerByID(mockJXPathContext, targetId)).thenReturn(null);

            Object result = functionIDMethod.invoke(coreFunction, mockContext);

            assertEquals(null, result);
        }
    }
}
